using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService(IServiceScopeFactory scopeFactory) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        using var scope = scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<Data.ApplicationDbContext>();

        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<Data.ShipmentStatus>(statusFilter, true, out var status))
            query = query.Where(s => s.Status == status);

        if (!string.IsNullOrWhiteSpace(searchTerm))
            query = query.Where(s =>
                s.TrackingNumber.Contains(searchTerm) ||
                s.Destination.Contains(searchTerm) ||
                s.RecipientName.Contains(searchTerm));

        return await query
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        using var scope = scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<Data.ApplicationDbContext>();

        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        using var scope = scopeFactory.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<Data.ApplicationDbContext>();

        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null)
            return null;

        shipment.Status = (Data.ShipmentStatus)newStatus;
        await db.SaveChangesAsync();
        return MapToDto(shipment);
    }

    private static ShipmentDto MapToDto(Data.Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        RecipientName = s.RecipientName,
        Description = s.Description
    };
}

