using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        group.MapGet("/", async (
            [FromQuery] string? status,
            [FromQuery] string? search,
            IShipmentService service) =>
        {
            var shipments = await service.GetShipmentsAsync(status, search);
            return Results.Ok(shipments);
        });

        group.MapGet("/track/{trackingNumber}", async (
            string trackingNumber,
            IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).AllowAnonymous();

        group.MapPut("/{id:int}/status", async (
            int id,
            [FromBody] StatusUpdateRequest request,
            IShipmentService service) =>
        {
            var shipment = await service.UpdateShipmentStatusAsync(id, request.Status);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });
    }

    public record StatusUpdateRequest(ShipmentStatus Status);
}

