arguments.new_str:
@page "/"

<PageTitle>ShipmentTracker — Home</PageTitle>

<div class="text-center py-4">
    <h1>📦 Shipment Tracker</h1>
    <p class="lead">Track your shipments in real time, anywhere in the world.</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="card shadow-sm">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260001)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                        Track
                    </button>
                </div>
            </div>
        </div>
    </div>
</div>

@inject NavigationManager Navigation

@code {
    private string trackingNumber = string.Empty;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            TrackShipment();
    }
}

arguments.file_text:
@page "/track/{TrackingNumber}"
@inject ShipmentTracker.Client.Services.IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>Shipment Tracking</h2>

@if (isLoading)
{
    <p><em>Loading...</em></p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number <code>@TrackingNumber</code>.
    </div>
    <a href="/" class="btn btn-outline-primary">← Back to search</a>
}
else
{
    <div class="card shadow-sm">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @StatusBadgeClass(shipment.Status)">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Description</div>
                <div class="col-sm-8">@shipment.Description</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Recipient</div>
                <div class="col-sm-8">@shipment.RecipientName</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Origin</div>
                <div class="col-sm-8">@shipment.Origin</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Destination</div>
                <div class="col-sm-8">@shipment.Destination</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Shipped</div>
                <div class="col-sm-8">@shipment.ShippedDate.ToString("MMMM d, yyyy")</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Estimated Delivery</div>
                <div class="col-sm-8">@shipment.EstimatedDelivery.ToString("MMMM d, yyyy")</div>
            </div>

            @{
                var steps = new[] { "Pending", "PickedUp", "InTransit", "OutForDelivery", "Delivered" };
                var currentStep = shipment.Status == ShipmentTracker.Client.Models.ShipmentStatus.Cancelled
                    ? -1
                    : (int)shipment.Status;
            }
            <div class="mt-3">
                <div class="d-flex justify-content-between">
                    @for (var i = 0; i < steps.Length; i++)
                    {
                        var stepClass = i <= currentStep ? "text-success fw-bold" : "text-muted";
                        <span class="@stepClass small">@FormatStep(steps[i])</span>
                    }
                </div>
                <div class="progress mt-1" style="height: 8px;">
                    <div class="progress-bar bg-success" style="width: @(currentStep >= 0 ? (currentStep * 25) : 0)%"></div>
                </div>
            </div>
        </div>
    </div>
    <a href="/" class="btn btn-outline-primary mt-3">← Track another shipment</a>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private ShipmentTracker.Client.Models.ShipmentDto? shipment;
    private bool isLoading = true;

    protected override async Task OnParametersSetAsync()
    {
        isLoading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        isLoading = false;
    }

    private static string StatusBadgeClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "bg-primary",
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentTracker.Client.Models.ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStep(string step) => step switch
