@page "/shipments"
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject ShipmentTracker.Client.Services.IShipmentService ShipmentService

<PageTitle>Shipments — Dispatcher View</PageTitle>

<h2>Shipments</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient..."
               @bind="searchTerm" @bind:event="oninput" @onkeydown="HandleSearchKey" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentTracker.Client.Models.ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-primary w-100" @onclick="LoadShipments">Search</button>
    </div>
</div>

@if (isLoading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Recipient</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in shipments)
                {
                    <tr>
                        <td><a href="/track/@s.TrackingNumber">@s.TrackingNumber</a></td>
                        <td>@s.RecipientName</td>
                        <td>@s.Destination</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <select class="form-select form-select-sm" @bind="newStatus">
                                    @foreach (var status in Enum.GetValues<ShipmentTracker.Client.Models.ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="badge @StatusBadgeClass(s.Status)">@s.Status</span>
                            }
                        </td>
                        <td>@s.EstimatedDelivery.ToString("MMM d, yyyy")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <button class="btn btn-sm btn-success me-1" @onclick="() => SaveStatus(s)" disabled="@isSaving">
                                    @(isSaving ? "Saving..." : "Save")
                                </button>
                                <button class="btn btn-sm btn-outline-secondary" @onclick="CancelEdit">Cancel</button>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">Update Status</button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

